window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b02a297505605fe9"]={"versions": [{"id": "FIG-b02a297505605fe9", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Ablaufdiagramm zur Darstellung einer Ausführungsreihenfolge-Bedingung (Execution Order Constraint, EOC) im Kontext des AUTOSAR-Zeitmodells und des Logical Execution Time (LET) Paradigmas. Das Diagramm modelliert die Vorgänger-Nachfolger-Beziehung zwischen ausführbaren Einheiten (Executable Entities) innerhalb desselben LET-Intervalls oder Executable Entity Clusters (EEC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>EE1</strong> (<code>Executable Entity 1</code>): Ausführbare Einheit (z. B. Runnable Entity), dargestellt als kreisförmiger Knoten mit hellblauer Füllung und schwarzer Umrandung, fungierend als Vorgänger (Predecessor).</li>\n<li><strong>EE2</strong> (<code>Executable Entity 2</code>): Ausführbare Einheit, dargestellt als kreisförmiger Knoten mit hellblauer Füllung und schwarzer Umrandung, fungierend als Nachfolger (Successor bzw. Direct Successor).</li>\n<li><strong>Gerichteter Pfeil</strong>: Gerichtete Verbindung von EE1 nach EE2, die eine strikte Ausführungsreihenfolge (<code>Execution Order Constraint</code>) repräsentiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Instanzen von <code>EE1</code> und <code>EE2</code> werden innerhalb desselben LET-Intervalls zur Ausführung geplant.</li>\n<li>Die gerichtete Kante erzwingt, dass die Instanz von <code>EE1</code> vor der Instanz von <code>EE2</code> ausgeführt werden muss (Reihenfolge 1 -> 2).</li>\n<li><code>EE2</code> ist als Nachfolger bzw. direkter Nachfolger von <code>EE1</code> markiert; die Ausführung von <code>EE2</code> darf erst nach vollständiger Beendigung von <code>EE1</code> stattfinden.</li>\n<li>Das Gesamtsystem der Execution Order Constraints muss zyklenfrei sein (<code>cycle-free</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Zyklenfreiheit</strong>: Gemäß AUTOSAR-Spezifikation darf eine Menge von EOCs keine zyklischen Abhängigkeiten aufweisen, um Deadlocks und widersprüchliche Ausführungsanforderungen zu verhindern.</li>\n<li><strong>LET-Gültigkeitsbereich</strong>: Die Ausführungsreihenfolgebeschränkung bindet Instanzen von Executable Entities innerhalb eines gemeinsamen LET-Intervalls.</li>\n<li><strong>RTE- und OS-Konfiguration</strong>: Die EOCs dienen Werkzeugen zur Generierung von OS-Tasks, Task-Ablaufplänen oder RTE-Schedule-Tabellen als Randbedingung für das Task-Mapping und die Ablaufsequenzierung.</li>\n</ul>"}, {"id": "FIG-5ec97520dee70f4e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Ablaufdiagramm zur Darstellung einer Ausführungsreihenfolge-Bedingung (Execution Order Constraint, EOC) im Kontext des AUTOSAR-Zeitmodells und des Logical Execution Time (LET) Paradigmas. Das Diagramm modelliert die Vorgänger-Nachfolger-Beziehung zwischen ausführbaren Einheiten (Executable Entities) innerhalb desselben LET-Intervalls oder Executable Entity Clusters (EEC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>EE1</strong> (<code>Executable Entity 1</code>): Ausführbare Einheit (z. B. Runnable Entity), dargestellt als kreisförmiger Knoten mit hellblauer Füllung und schwarzer Umrandung, fungierend als Vorgänger (Predecessor).</li>\n<li><strong>EE2</strong> (<code>Executable Entity 2</code>): Ausführbare Einheit, dargestellt als kreisförmiger Knoten mit hellblauer Füllung und schwarzer Umrandung, fungierend als Nachfolger (Successor bzw. Direct Successor).</li>\n<li><strong>Gerichteter Pfeil</strong>: Gerichtete Verbindung von EE1 nach EE2, die eine strikte Ausführungsreihenfolge (<code>Execution Order Constraint</code>) repräsentiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Instanzen von <code>EE1</code> und <code>EE2</code> werden innerhalb desselben LET-Intervalls zur Ausführung geplant.</li>\n<li>Die gerichtete Kante erzwingt, dass die Instanz von <code>EE1</code> vor der Instanz von <code>EE2</code> ausgeführt werden muss (Reihenfolge 1 -> 2).</li>\n<li><code>EE2</code> ist als Nachfolger bzw. direkter Nachfolger von <code>EE1</code> markiert; die Ausführung von <code>EE2</code> darf erst nach vollständiger Beendigung von <code>EE1</code> stattfinden.</li>\n<li>Das Gesamtsystem der Execution Order Constraints muss zyklenfrei sein (<code>cycle-free</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Zyklenfreiheit</strong>: Gemäß AUTOSAR-Spezifikation darf eine Menge von EOCs keine zyklischen Abhängigkeiten aufweisen, um Deadlocks und widersprüchliche Ausführungsanforderungen zu verhindern.</li>\n<li><strong>LET-Gültigkeitsbereich</strong>: Die Ausführungsreihenfolgebeschränkung bindet Instanzen von Executable Entities innerhalb eines gemeinsamen LET-Intervalls.</li>\n<li><strong>RTE- und OS-Konfiguration</strong>: Die EOCs dienen Werkzeugen zur Generierung von OS-Tasks, Task-Ablaufplänen oder RTE-Schedule-Tabellen als Randbedingung für das Task-Mapping und die Ablaufsequenzierung.</li>\n</ul>"}], "trans": [{"from": "FIG-b02a297505605fe9", "to": "FIG-5ec97520dee70f4e", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
